import (
	"net"
	"net/http"
	"net/netip"
	"net/url"
	"regexp"
	"sort"
	"strings"
)

// Leak is one finding of CheckLeaks. It names where and which rule, never what
// matched: a field for the matched text would put a secret in a test log.
type Leak struct {
	Fixture string
	Line    int // 1-based
	Rule    string
}

// AllowedHosts are the only hosts a fixture may name, in a URL or a Host
// header: the loopback address the bench is published on and the bench's own
// proxy upstream (the one internal/nexusbench/testdata/descriptor.example.json
// names). The bench's LAN addresses are not allowed.
var AllowedHosts = []string{"127.0.0.1", "bench-upstream.nexus-bench.svc.cluster.local"}

// The rules, by the name a Leak carries.
const (
	ruleAuthorization  = "authorization-not-redacted"
	ruleSession        = "cookie-or-session"
	ruleHeaderAllowed  = "response-header-outside-allowlist"
	ruleRequestHeader  = "request-header-outside-allowlist"
	ruleMalformed      = "malformed-header-line"
	ruleJWT            = "jwt-like-value"
	ruleSecretFormat   = "secret-token-format"
	ruleJSONSecret     = "REDACTED"
	ruleHost           = "host-not-allowed"
	rulePrivateAddress = "private-or-link-local-address"
	ruleInternalName   = "internal-name-or-path"
	ruleQuery          = "request-query-outside-allowlist"
	ruleExactTerm      = "exact-term"
)

// sessionKV is the name of the Nexus session cookie, refused anywhere in a fixture.
const sessionKV = "NXSESSIONID"

var (
	jwtLike = regexp.MustCompile(`eyJ[A-Za-z0-9_-]{10,}`)
	// secretFormat matches well-known secret formats: GitHub and GitLab tokens,
	// AWS access key ids, and the first line of a PEM private key.
	secretFormat = regexp.MustCompile(
		`gh[pousr]_[A-Za-z0-9]{36,}|glpat-[A-Za-z0-9_-]{20,}|(?:AKIA|ASIA)[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----`)
	// urlAuth reads the authority of a URL, also when its slashes are JSON-escaped.
	urlAuth = regexp.MustCompile(`(?i)https?:\\?/\\?/([^\s/"'<>?#\\,;)]+)`)
	// ipv4Like needs a non-numeric character before the address, not a word boundary:
	// "ip10.1.2.3" holds one.
	ipv4Like = regexp.MustCompile(`(?:^|[^0-9])(\d{1,3}(?:\.\d{1,3}){3})`)
	// ipv6Local starts a unique-local (fc00::/7) or link-local (fe80::/10) address.
	ipv6Local = regexp.MustCompile(`(?i)(?:^|[^0-9a-f])(?:f[cd][0-9a-f]{2}|fe[89ab][0-9a-f]):`)
	// bareHost is a host name in an internal zone; the group is the name.
	bareHost = regexp.MustCompile(`(?i)([a-z0-9_-]+(?:\.[a-z0-9_-]+)*\.(?:home\.arpa|lan|internal|local))(?:$|[^a-z0-9_-])`)
	// localPath is a user's home directory anchored at the start of a value (after
	// a quote, a blank or "="): "/home/" inside an image path is legitimate.
	// winProfile is a Windows profile path, raw or JSON-escaped.
	localPath  = regexp.MustCompile(`(?:^|["\s=])/(?:root|home|Users)/`)
	winProfile = regexp.MustCompile(`(?i)[a-z]:\\+users`)

	cgnat = netip.MustParsePrefix("100.64.0.0/10")

	sessionHeaders = []string{"cookie", "set-cookie", "x-nexus-ui"}
	// internalNames are matched ignoring case.
	internalNames = []string{"datomir", "secrets.json", "xdg_state_home"}
	// queryParams are the only parameters a request URL may carry (the paging of _catalog).
	queryParams = []string{"n", "last"}
	// jsonEscaper writes a term as it sits inside a JSON string.
	jsonEscaper = strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
)

// lineState is where a line sits in the file: the commented header, or one of
// the parts of an exchange.
type lineState int

const (
	stMeta lineState = iota
	stReqLine
	stReqHeaders
	stRespLine
	stRespHeaders
	stBody
)

// CheckLeaks scans one fixture, line by line (lines count from 1), for what a
// fixture must not hold: an Authorization other than the placeholders, a cookie
// or session header, a request header outside Host, Authorization and Accept, a
// response header outside ResponseHeaderAllowlist, a line of a header section
// that is not "Name: value", a request query parameter other than n and last, a
// JWT-like value or another well-known secret format, a JSON secret key whose
// value is not "<redacted>" (or null), a host outside AllowedHosts, a private,
// link-local, CGNAT or unique-local address, an internal name or local path, and
// each term of exact (recorder passwords and their Basic encodings, or an
// external deny list), also in another case, JSON-escaped or URL-escaped; an
// empty term matches nothing. The text is scanned as written, not parsed: a file
// that does not parse is still checked.
func CheckLeaks(fixture string, data []byte, exact []string) []Leak {
	c := &leakScan{fixture: fixture, seen: map[leakKey]bool{}, exact: exactVariants(exact)}
	text := string(data)
	state := stMeta
	for i, line := range strings.Split(text, "\n") {
		state = c.scanLine(i+1, line, state)
	}
	c.scanJSONSecrets(text)
	sort.SliceStable(c.leaks, func(i, j int) bool { return c.leaks[i].Line < c.leaks[j].Line })
	return c.leaks
}

// exactVariants lists, lower-cased, the forms of each term that can sit in a
// fixture: as given, JSON-escaped, URL-escaped as a query value and as a path.
func exactVariants(terms []string) []string {
	var out []string
	for _, term := range terms {
		if term == "" {
			continue
		}
		for _, v := range []string{term, jsonEscaper.Replace(term), url.QueryEscape(term), url.PathEscape(term)} {
			out = append(out, strings.ToLower(v))
		}
	}
	return out
}

type leakKey struct {
	line int
	rule string
}

type leakScan struct {
	fixture string
	exact   []string // lower-cased variants of the exact terms
	leaks   []Leak
	seen    map[leakKey]bool

package nexusfixture

import (
	"bytes"
	"fmt"
	"net/http"
	"net/textproto"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Identity is the account a fixture was recorded as; it comes from the file
// name suffix only.
type Identity string

// The identities of the NX-03 bench.
const (
	Admin     Identity = "admin"
	Pull      Identity = "pull"
	Anonymous Identity = "anon"
)

// RecordPending marks a request-only fixture that the recorder has yet to fill.
const RecordPending = "pending"

const (
	fileSuffix    = ".http"
	identitySep   = "--"
	exchangeSep   = "###"
	httpVersion   = "HTTP/1.1"
	stubEmpty     = "<empty body>"
	stubHTMLStart = "<HTML body omitted:"
	// stubOmittedStart opens the summary of a body that is neither JSON nor HTML.
	stubOmittedStart = "<body omitted:"
)

// Meta is the commented header of a fixture. Free text is kept raw so that
// Format loses nothing.
type Meta struct {
	Scenario     string // the "# scenario:" header, free text; Fixture.Scenario is the file name's part
	NexusVersion string // first token of the nexus header
	Edition      string // second token of the nexus header
	NexusNote    string // the text in parentheses after the edition, without them
	Measured     string // raw value: a date, optionally followed by ", free text"
	Account      string
	Redacted     string
	State        string // "" = nominal
	Record       string // "" = replay, "replay", "pending" or "skip: <reason>"
	RecordedBy   string // "" for an imported NX-03 file
}

// Exchange is one request and its answer. A request-only exchange (a pending
// fixture) has Status 0 and no response part.
type Exchange struct {
	Method, Target, Host string // Target = path + raw query as recorded
	RequestHeader        http.Header
	Status               int
	Reason               string      // reason phrase as recorded; http.StatusText when empty
	Header               http.Header // response, whitelisted
	Body                 []byte      // verbatim; nil when Stub != ""
	Stub                 string      // "<empty body>" or the HTML summary, as written
}

// Fixture is one file: a header and one or more exchanges.
type Fixture struct {
	// Name is the file name without ".http"; Scenario is the part of Name before
	// the identity suffix. Meta.Scenario is a different thing: the free text of the
	// "# scenario:" header, which need not match the file name.
	Campaign, Name, Scenario string
	Identity                 Identity
	Meta                     Meta
	Exchanges                []Exchange
}

var (
	versionPattern = regexp.MustCompile(`^\d+(\.\d+)+(-[0-9A-Za-z.]+)?$`)

	requiredHeaders = []string{"scenario", "nexus", "measured", "account", "redacted"}
	optionalHeaders = []string{"state", "record", "recorded-by"}

	requestOrder  = []string{"Authorization", "Accept"}
	responseOrder = []string{
		"Server", "Docker-Distribution-Api-Version", "Www-Authenticate", "Location", "Link",
		"Docker-Content-Digest", "Content-Type", "Content-Length",
	}
	// displayNames are the header names whose written form is not the
	// canonical one Go uses as a map key.
	displayNames = map[string]string{"Www-Authenticate": "WWW-Authenticate"}
)

func parseErr(fileName, format string, args ...any) error {
	return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
}

// Parse reads one fixture file. fileName is the base name, with ".http". A file
// is LF only: a carriage return anywhere is refused. A body line made of "###"
// preceded by any number of backslashes is read with one backslash less (Format
// writes it with one more), so that a body never reads as the exchange separator.
func Parse(campaign, fileName string, data []byte) (Fixture, error) {
	f := Fixture{Campaign: campaign}
	name, ok := strings.CutSuffix(fileName, fileSuffix)
	if !ok {
		return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
	}
	f.Name = name
	i := strings.LastIndex(name, identitySep)
	if i < 0 {
		return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
	}
	f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
	switch f.Identity {
	case Admin, Pull, Anonymous:
	default:
		return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
	}

	if bytes.IndexByte(data, '\r') >= 0 {
		return f, parseErr(fileName, "the file has a carriage return (CRLF line endings): fixtures use LF only")
	}

	meta, rest, err := parseMeta(string(data))
	if err != nil {
		return f, parseErr(fileName, "%v", err)
	}
	f.Meta = meta

	chunks := splitExchanges(rest)
	for n, chunk := range chunks {
		ex, err := parseExchange(chunk, meta.Record == RecordPending)
		if err != nil {
			if len(chunks) > 1 {
				return f, parseErr(fileName, "exchange %d: %v", n+1, err)
			}
			return f, parseErr(fileName, "%v", err)
		}
		f.Exchanges = append(f.Exchanges, ex)
	}
	return f, nil
}

// nextLine cuts the first line of s; ok is false when s is empty.
func nextLine(s string) (line, rest string, ok bool) {
	}
}

// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
// the recorder or the NX-03 import wrote.
func Format(f Fixture) []byte {
	var b bytes.Buffer
	writeMeta(&b, f.Meta)
	for i, ex := range f.Exchanges {
		if i == 0 {
			b.WriteString("\n")
		} else {
			b.WriteString(exchangeSep + "\n")
		}
		writeExchange(&b, ex)
	}
	return b.Bytes()
}

func writeMeta(b *bytes.Buffer, m Meta) {
	nexus := m.NexusVersion + " " + m.Edition
	if m.NexusNote != "" {
		nexus += " (" + m.NexusNote + ")"
	}
	lines := []struct{ key, value string }{
		{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
		{"account", m.Account}, {"redacted", m.Redacted},
	}
	for _, l := range lines {
		fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
	}
	for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
		if l.value != "" {
			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
		}
	}
}

func writeExchange(b *bytes.Buffer, ex Exchange) {
	fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
	writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
	if ex.Status == 0 {
		return
	}
	reason := ex.Reason
	if reason == "" {
		reason = http.StatusText(ex.Status)
	}
	b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
	writeHeaders(b, ex.Header, responseOrder)
	b.WriteString("\n")
	if ex.Stub != "" {
		b.WriteString(ex.Stub)
	} else {
		b.Write(escapeBody(ex.Body))
	}
	b.WriteString("\n")
}

// writeHeaders writes the headers in a fixed order (the preferred names first,
// then the others sorted) so that a regeneration does not reshuffle a file.
func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
	skipped := map[string]bool{}
	for _, s := range skip {
		skipped[s] = true
	}
	var names []string
	for _, p := range preferred {
		if _, ok := h[p]; ok && !skipped[p] {
			names = append(names, p)
		}
	}
	var others []string
	for k := range h {
		if skipped[k] || contains(preferred, k) {
			continue
		}
		others = append(others, k)
	}
	sort.Strings(others)
	for _, name := range append(names, others...) {
		display := name
		if d, ok := displayNames[name]; ok {
			display = d
		}
		for _, v := range h[name] {
			fmt.Fprintf(b, "%s: %s\n", display, v)
		}
	}
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}
package nexusbench

import (
	"context"
	"io"
	"net/http"
	"strings"
	"time"
)

// probeTimeout bounds one probe, connection included: the wait asks again at
// its next round, so a short one is enough and a silent host costs little.
const probeTimeout = 5 * time.Second

// probeOp names the probe in its errors.
const probeOp = "probe the Nexus status"

// Prober tells whether a Nexus answers on baseURL ("http://host:port").
type Prober interface {
	// Ready returns nil when GET <baseURL>/service/rest/v1/status answers 200,
	// and an error otherwise, whatever the reason.
	Ready(ctx context.Context, baseURL string) error
}

// httpProber is the Prober of the command.
type httpProber struct {
	http *http.Client
}

// NewProber returns the Prober that asks the instance over HTTP. It sends one
// unauthenticated GET, follows no redirection, goes through no proxy, and never
// reads or reports the body of the answer.
func NewProber() Prober {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = nil
	// One probe per round: keeping the connection alive would only hold a socket
	// open on a pod that may be restarting.
	transport.DisableKeepAlives = true
	return &httpProber{http: &http.Client{
		Timeout:       probeTimeout,
		Transport:     transport,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}}
}

// Ready implements Prober. The error is a *transportError (no answer) or an
// *APIError (an answer other than 200); neither prints the URL or the body.
func (pr *httpProber) Ready(ctx context.Context, baseURL string) error {
	target := strings.TrimRight(baseURL, "/") + restStatusPath
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
	if err != nil {
		return &transportError{Op: probeOp, Err: err}
	}
	resp, err := pr.http.Do(req)
	if err != nil {
		return &transportError{Op: probeOp, Err: err}
	}
	defer func() { _ = resp.Body.Close() }()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, drainBytes))
	if resp.StatusCode != http.StatusOK {
		return &APIError{Op: probeOp, Status: resp.StatusCode}
	}
	return nil
}
